// Sprite-sheet extraction only. Artwork is generated by image_gen; no shapes are painted here.
import fs from 'node:fs'
import path from 'node:path'
import crypto from 'node:crypto'
import sharp from 'sharp'
import { buildings } from '../../src/v4/data/buildings'
import { scenicSizes } from '../../src/v4/render/graphics'

const root = 'assets/v5/pixel',
  out = `${root}/buildings`
fs.mkdirSync(out, { recursive: true })
type Cut = { data: Buffer; w: number; h: number; baseLeft: number; baseRight: number }
type Entry = {
  file: string
  width: number
  height: number
  ax: number
  ay: number
  scale: number
  level: number
  id: string
  footprint: { width: number; height: number }
  emitter?: { x: number; y: number }
}
const manifest: Record<string, Entry> = {}
const gutterCache = new Map<string, Promise<number[]>>()
function gutters(sheet: string, axis: 'x' | 'y', parts: number) {
  const key = `${sheet}:${axis}:${parts}`
  if (!gutterCache.has(key))
    gutterCache.set(
      key,
      (async () => {
        const { data, info } = await sharp(sheet)
          .ensureAlpha()
          .raw()
          .toBuffer({ resolveWithObject: true })
        const size = axis === 'x' ? info.width : info.height,
          cross = axis === 'x' ? info.height : info.width,
          edges = [0]
        for (let boundary = 1; boundary < parts; boundary++) {
          let start = -1,
            bestStart = 0,
            bestLength = 0
          for (
            let a = Math.floor(size * (boundary / parts - 0.1));
            a <= Math.floor(size * (boundary / parts + 0.1));
            a++
          ) {
            let count = 0
            for (let b = 0; b < cross; b++) {
              const x = axis === 'x' ? a : b,
                y = axis === 'x' ? b : a
              if (data[(y * info.width + x) * 4 + 3] >= 180) count++
            }
            if (count <= 3) {
              if (start < 0) start = a
              if (a - start > bestLength) {
                bestStart = start
                bestLength = a - start
              }
            } else start = -1
          }
          if (bestLength < 2) throw new Error(`No safe ${axis} gutter ${boundary} in ${sheet}`)
          edges.push((bestStart + bestLength / 2) / size)
        }
        return [...edges, 1]
      })(),
    )
  return gutterCache.get(key)!
}
async function cut(sheet: string, index: number, cols: number, rows: number): Promise<Cut> {
  const m = await sharp(sheet).metadata()
  // Detect actual transparent gutters; generated sheets do not guarantee equal cell sizes.
  const xs = await gutters(sheet, 'x', cols)
  const ys = await gutters(sheet, 'y', rows)
  const col = index % cols,
    row = Math.floor(index / cols)
  const leftEdge = Math.round(xs[col] * m.width!),
    topEdge = Math.round(ys[row] * m.height!)
  const cw = Math.round(xs[col + 1] * m.width!) - leftEdge,
    ch = Math.round(ys[row + 1] * m.height!) - topEdge
  const { data, info } = await sharp(sheet)
    .extract({
      left: leftEdge,
      top: topEdge,
      width: cw,
      height: ch,
    })
    .ensureAlpha()
    .raw()
    .toBuffer({ resolveWithObject: true })
  // Remove detached generation specks before measuring the slab, retaining real components.
  const visited = new Uint8Array(cw * ch),
    components: number[][] = []
  for (let n = 0; n < cw * ch; n++) {
    if (visited[n] || data[n * 4 + 3] < 180) continue
    const queue = [n]
    visited[n] = 1
    for (let j = 0; j < queue.length; j++) {
      const p = queue[j],
        x = p % cw,
        y = Math.floor(p / cw)
      for (const q of [
        x ? p - 1 : -1,
        x + 1 < cw ? p + 1 : -1,
        y ? p - cw : -1,
        y + 1 < ch ? p + cw : -1,
      ])
        if (q >= 0 && !visited[q] && data[q * 4 + 3] >= 180) {
          visited[q] = 1
          queue.push(q)
        }
    }
    components.push(queue)
  }
  const largest = Math.max(...components.map(c => c.length)),
    keep = new Uint8Array(cw * ch)
  for (const c of components)
    if (c.length >= Math.max(20, largest * 0.01)) for (const p of c) keep[p] = 1
  let left = cw,
    right = 0,
    top = ch,
    bottom = 0
  for (let y = 0; y < ch; y++)
    for (let x = 0; x < cw; x++) {
      const i = (y * cw + x) * 4
      data[i + 3] = keep[y * cw + x] ? 255 : 0
      if (!data[i + 3]) continue
      left = Math.min(left, x)
      right = Math.max(right, x)
      top = Math.min(top, y)
      bottom = Math.max(bottom, y)
    }
  if (right <= left || bottom <= top) throw new Error(`Empty cell ${sheet}:${index}`)
  if (left === 0 || top === 0 || right === cw - 1 || bottom === ch - 1)
    throw new Error(`Cell touches cut edge; review extraction ${sheet}:${index}`)
  let baseLeft = left,
    baseRight = right,
    best = 0
  // The foundation is the broad opaque strip along the bottom, not the tallest object.
  for (let y = Math.max(top, bottom - 20); y <= bottom; y++) {
    let a = cw,
      b = 0,
      count = 0
    for (let x = left; x <= right; x++) {
      const i = (y * cw + x) * 4,
        c = [data[i], data[i + 1], data[i + 2]]
      if (data[i + 3] && Math.max(...c) - Math.min(...c) < 38 && c[0] > 35) {
        a = Math.min(a, x)
        b = Math.max(b, x)
        count++
      }
    }
    if (count > best && b - a > (right - left) * 0.65) {
      best = count
      baseLeft = a
      baseRight = b
    }
  }
  const w = right - left + 1,
    h = bottom - top + 1
  const cropped = await sharp(data, { raw: { width: cw, height: ch, channels: info.channels } })
    .extract({ left, top, width: w, height: h })
    .raw()
    .toBuffer()
  return { data: cropped, w, h, baseLeft: baseLeft - left, baseRight: baseRight - left + 1 }
}
async function build(
  id: string,
  w: number,
  d: number,
  cuts: Cut[],
  foundation = true,
  contentWidth = w * 64,
) {
  const rendered = []
  for (const c of cuts) {
    const span = foundation ? c.baseRight - c.baseLeft : c.w,
      k = contentWidth / span
    const width = Math.round(c.w * k),
      height = Math.round(c.h * k)
    const data = await sharp(c.data, { raw: { width: c.w, height: c.h, channels: 4 } })
      .resize(width, height, { kernel: 'nearest' })
      .png({ palette: true, colours: 96, dither: 0 })
      .toBuffer()
    rendered.push({
      data,
      width,
      height,
      centre: (foundation ? (c.baseLeft + c.baseRight) / 2 : c.w / 2) * k,
    })
  }
  const width =
      Math.ceil(
        Math.max(w * 32 + 8, ...rendered.map(r => Math.max(r.centre, r.width - r.centre) + 4)),
      ) * 2,
    height = Math.max(d * 64 + 8, ...rendered.map(r => r.height + 8)),
    ax = width / 2,
    ay = height - 4
  for (let i = 0; i < 5; i++) {
    const r = rendered[Math.min(i, rendered.length - 1)],
      x = Math.round(ax - r.centre),
      y = ay - r.height
    // Allow small pipe overhang, but never clip it silently.
    if (x < 0 || x + r.width > width)
      throw new Error(`${id}: horizontal overhang needs review (${x}, ${r.width}, frame ${width})`)
    const file = `${id}_L${i + 1}.png`
    await sharp({ create: { width, height, channels: 4, background: '#00000000' } })
      .composite([{ input: r.data, left: x, top: y }])
      .png({ palette: true, colours: 96, dither: 0 })
      .toFile(`${out}/${file}`)
    const entry: Entry = {
      id,
      level: i + 1,
      file,
      width,
      height,
      ax,
      ay,
      scale: 0.5,
      footprint: { width: w * 64, height: d * 64 },
    }
    if (['cdu', 'cracker', 'flare'].includes(id)) {
      const raw = await sharp(r.data).ensureAlpha().raw().toBuffer()
      let sum = 0,
        count = 0
      for (let yy = 0; yy < Math.min(6, r.height); yy++)
        for (let xx = 0; xx < r.width; xx++)
          if (raw[(yy * r.width + xx) * 4 + 3] > 200) {
            sum += xx
            count++
          }
      entry.emitter = {
        x: Math.round((x + (count ? sum / count : r.width / 2) - ax) / 2),
        y: Math.round((y - ay) / 2),
      }
    }
    manifest[`${id}:${i + 1}`] = entry
  }
}
async function main() {
  for (const b of buildings.filter(b => b.category !== 'deco' && b.id !== 'road')) {
    const sheet = `${root}/source/${b.id}.png`
    if (!fs.existsSync(sheet)) continue
    await build(
      b.id,
      b.w,
      b.h,
      await Promise.all(Array.from({ length: 5 }, (_, i) => cut(sheet, i, 3, 2))),
    )
  }
  if (fs.existsSync(`${root}/source/gate_w.png`))
    await build(
      'gate_w',
      1,
      2,
      await Promise.all(
        Array.from({ length: 5 }, (_, i) => cut(`${root}/source/gate_w.png`, i, 3, 2)),
      ),
    )
  const props = [
    'warehouse',
    'house',
    'office',
    'crane',
    'containers',
    'utility',
    'rocks',
    'flowerbed',
  ]
  if (fs.existsSync(`${root}/source/scenery.png`))
    for (const [i, id] of props.entries()) {
      const d = scenicSizes[id]
      await build(id, d.w, d.h, [await cut(`${root}/source/scenery.png`, i, 3, 3)], i < 6)
    }
  const decos = buildings.filter(b => b.category === 'deco')
  if (fs.existsSync(`${root}/source/decorations.png`))
    for (const [i, d] of decos.entries())
      await build(
        d.id,
        1,
        1,
        [await cut(`${root}/source/decorations.png`, i, 4, 3)],
        false,
        d.id === 'lamp' ? 16 : d.id === 'flag' ? 40 : 64,
      )
  if (fs.existsSync(`${root}/source/terrain.png`)) {
    const sheet = sharp(`${root}/source/terrain.png`),
      m = await sheet.metadata(),
      tw = m.width! / 3,
      th = m.height! / 2
    for (const [i, id] of ['concrete', 'asphalt', 'quay', 'grass', 'soil', 'sea'].entries()) {
      await sharp(`${root}/source/terrain.png`)
        .extract({ left: (i % 3) * tw, top: Math.floor(i / 3) * th, width: tw, height: th })
        .resize(64, 64, { kernel: 'nearest' })
        .removeAlpha()
        .png({ palette: true, colours: 48, dither: 0 })
        .toFile(`${root}/${id}.png`)
    }
    for (let level = 1; level <= 5; level++) {
      const file = `road_L${level}.png`
      fs.copyFileSync(`${root}/asphalt.png`, `${out}/${file}`)
      manifest[`road:${level}`] = {
        id: 'road',
        level,
        file,
        width: 64,
        height: 64,
        ax: 32,
        ay: 64,
        scale: 0.5,
        footprint: { width: 64, height: 64 },
      }
    }
  }
  const lines = [
    '// Generated from image_gen artwork by scripts/art/build-generated-pixel.ts.',
    "import type { SpriteImage, Tier } from './spriteImages'",
    'export const pixelBuildings: Record<string, Partial<Record<Tier, SpriteImage>>> = {',
  ]
  for (const id of new Set(Object.values(manifest).map(m => m.id))) {
    lines.push(`  ${id}: {`)
    for (const m of Object.values(manifest).filter(m => m.id === id))
      lines.push(
        `    ${m.level}: { src: require('../../../${out}/${m.file}'), w:${m.width},h:${m.height},ax:${m.ax},ay:${m.ay},scale:0.5,smooth:false${m.emitter ? `,emitter:${JSON.stringify(m.emitter)}` : ''}},`,
      )
    lines.push('  },')
  }
  lines.push('}')
  fs.writeFileSync('src/v4/render/pixelBuildings.ts', lines.join('\n') + '\n')
  fs.writeFileSync(`${root}/manifest.json`, JSON.stringify(manifest, null, 2) + '\n')
  const sourceHashes = Object.fromEntries(
    fs
      .readdirSync(`${root}/source`)
      .filter(f => f.endsWith('.png'))
      .map(f => [
        f,
        crypto
          .createHash('sha256')
          .update(fs.readFileSync(path.join(root, 'source', f)))
          .digest('hex'),
      ]),
  )
  fs.writeFileSync(`${root}/source/SHA256.json`, JSON.stringify(sourceHashes, null, 2) + '\n')
  console.log(
    `Extracted ${Object.keys(manifest).length} generated pixel sprites at 64 art px / tile; no procedural painting.`,
  )
}
main().catch(e => {
  console.error(e)
  process.exitCode = 1
})
